BEGIN;
CREATE TABLE IF NOT EXISTS academic_years(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, starts_on DATE NOT NULL, ends_on DATE NOT NULL, CHECK(ends_on>=starts_on));
ALTER TABLE terms ADD COLUMN IF NOT EXISTS academic_year_id BIGINT REFERENCES academic_years;
CREATE TABLE IF NOT EXISTS help_articles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL UNIQUE, content TEXT NOT NULL, category TEXT NOT NULL, published BOOLEAN NOT NULL DEFAULT true);
INSERT INTO help_articles(title,content,category) VALUES
('How do I reset my password?','Choose Forgot password on the sign-in page. Google accounts manage passwords through Google.','Account access'),
('Where can I find my grades?','Open Grades. Scores appear after your teacher releases them. Final grades appear after your teacher finalizes and publishes the course result.','Courses & grades'),
('How do I submit an assignment?','Open Assignments, choose an assignment, enter your answer, and save before the deadline. You can then attach private files when storage is connected.','Courses & grades'),
('How do I change my enrollment?','Contact your administrator to update your program, year level, or enrolled classes.','Courses & grades'),
('Which timezone is used?','Your account timezone is saved in Settings. Recurring class timetables use the school timezone.','Technical support') ON CONFLICT(title) DO NOTHING;
ALTER TABLE assessments ADD COLUMN IF NOT EXISTS archived BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE submissions ADD COLUMN IF NOT EXISTS graded_at TIMESTAMPTZ;
COMMIT;
